-- 自動運転の追加作業・炭素源・日常分析方式。変更前指紋検査付き。適用済みなら再実行禁止。
begin;
select set_config('amd.cost_change_reason','まさ指示: 自動運転の追加作業、排ガス/空気、日常分析と定期外注',true);
do $$ begin
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from '0e94c30fb8f8058230dac94e221b5740' then raise exception 'fuel changed: project_cost_models'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_fuel_260914') is distinct from 'fe3036150eff376ab58405218b9348aa' then raise exception 'fuel changed: project_cost_assumptions'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b80c6219e74a52ef6ace596640168f64' then raise exception 'fuel changed: project_cost_items'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from 'fdee3c57a18b9baa57557444dfdc374a' then raise exception 'fuel changed: project_cost_tasks'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_fuel_260914') is distinct from 'cc4b9f616d7cb61d6e5228e7c96427e9' then raise exception 'fuel changed: project_cost_notes'; end if;
end $$;
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_carbon_source','cm_p21_fuel_260914',null,'炭素源と生産性','炭素源',null,'flue_gas',null,'H','仮置き','AMD（内部）',true,'fuel_carbon_source','排ガス・空気・購入CO₂を比較する。供給ガスの購入代と送気・前処理の追加費を分ける。','amd_internal',125,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_air_productivity_ratio','cm_p21_fuel_260914',null,'炭素源と生産性','空気供給での分泌生産性（排ガス比・比較用）',50,null,'%','H','仮置き','AMD（内部）',true,'fuel_air_productivity_ratio','SOLの空気供給時の分泌速度は未測定。50%は比較用の仮置きで、太陽光の比率と掛けて年間生産量に反映。出荷待ち期間を維持する。https://pmc.ncbi.nlm.nih.gov/articles/PMC6593468/','amd_internal',126,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_carbon_delivery_annual','cm_p21_fuel_260914',null,'炭素源と生産性','送気・前処理で増える費用',null,null,'円/年','H','仮置き','AMD（内部）',true,'fuel_carbon_delivery_annual','追加ブロワ電力、除塵・冷却・送気の年間差額。排水側で払う分と区分する。空欄は未見積。','amd_internal',127,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_air_co2_ppm','cm_p21_fuel_260914',null,'炭素源と生産性','空気中CO₂濃度（比較用）',400,null,'ppm','H','仮置き','AMD（内部）',true,'fuel_air_co2_ppm','供給気体量を比較するため400ppmを仮置き。全量吸収する理論最小ガス量を表示。吸収率と送気電力は別に測定する。','amd_internal',128,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_flue_co2_percent','cm_p21_fuel_260914',null,'炭素源と生産性','利用する排ガスのCO₂濃度',5,null,'%','H','仮置き','AMD（内部）',true,'fuel_flue_co2_percent','5%を比較用に仮置き。供給元の組成で更新。気体体積の理論最小値に用い、生産性は排ガス供給を基準とする。','amd_internal',129,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_quality_mode','cm_p21_fuel_260914',null,'日常分析と外部確認','品質確認の方式',null,'hybrid',null,'H','仮置き','AMD（内部）',true,'fuel_quality_mode','自社の日常管理と定期外部確認、各ロット外注を比較する。英国の運用例は自社検査と定期外部試験を併用。SOLの船舶向けの項目・頻度は取引先と決める。https://www.gov.uk/government/publications/biodiesel-quality-protocol/biodiesel-quality-protocol','amd_internal',130,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_qc_routine_hours','cm_p21_fuel_260914',null,'日常分析と外部確認','自社の日常分析で増える実作業',0.25,null,'人時/回','H','仮置き','AMD（内部）',true,'fuel_qc_routine_hours','酸価・水分等の日常管理の採取・分析・記録の追加実作業15分/品質ロットを比較用に仮置き。自動測定の待ち時間と区分し実測で更新する。','amd_internal',131,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_qc_routine_consumables','cm_p21_fuel_260914',null,'日常分析と外部確認','自社の日常分析の試薬・消耗品',1000,null,'円/回','H','仮置き','AMD（内部）',true,'fuel_qc_routine_consumables','日常の限定した管理項目について1000円/品質ロットを内部仮置き。全規格試験とは項目と頻度を分け、試薬・標準液・カラム等の実消費から更新する。','amd_internal',132,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_lab_capex','cm_p21_fuel_260914',null,'日常分析と外部確認','追加購入する分析機器の総額',null,null,'円','H','仮置き','AMD（内部）',true,'fuel_lab_capex','自社の日常分析のための追加購入総額。既存機器の共用なら追加購入差額を入力。燃料設備の追加購入欄との重複を除き、一度だけ償却する。見積前は空欄。','amd_internal',133,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_lab_life_years','cm_p21_fuel_260914',null,'日常分析と外部確認','追加分析機器の耐用年数',7,null,'年','H','仮置き','AMD（内部）',true,'fuel_lab_life_years','比較用に7年を仮置き。購入機器の見積・更新周期で変更する。','amd_internal',134,null,null);
insert into project_cost_assumptions (cost_assumption_id,cost_model_id,code,group_label,label,value,value_text,unit,confidence,source_kind,owner,is_key,role_key,note,visibility,sort_order,strain,application) values ('caf_auto_lab_annual','cm_p21_fuel_260914',null,'日常分析と外部確認','分析機器の校正・維持費',null,null,'円/年','H','仮置き','AMD（内部）',true,'fuel_lab_annual','校正・保守・標準試料・ガス等の年間追加費。日常分析の1回の消耗品との重複を除く。見積前は空欄。','amd_internal',135,null,null);
update project_cost_tasks set note='排水側の既存巡回に上乗せする追加確認15分/拠点日を内部仮置き。年300回で75人時。系列数を掛けず、追加時間を実測して更新。溶媒相・警報・漏れ・菌体影響を一巡で確認する。',label='自動運転の追加確認（拠点全体1日分）',group_label='分泌回収を監視する',count_driver='fixed',updated_at=now() where cost_task_id='ctf_sec_culture_operation';
update project_cost_tasks set note='自社転換の自動薬注・反応・分離を前提に、脂肪酸100kgごと追加実作業10分を内部仮置き。委託時は計上しない。実測で更新する。',label='自動FAME転換の追加作業（処理1回）',hours_per_occurrence=0.16666666666666666,updated_at=now() where cost_task_id='ctf_sec_inhouse_operation';
update project_cost_tasks set note='自動の送液・薬注・温度制御・分離・抜出しを前提に、脂肪酸100kgの処理1回ごとに補給・切替・確認・記録の追加実作業10分を内部仮置き。待ち時間は含めず実測で更新。保守・異常対応は別行。',label='自動回収の補給・切替・記録（処理1回）',hours_per_occurrence=0.16666666666666666,updated_at=now() where cost_task_id='ctf_sec_plant_operation';
update project_cost_tasks set note='各ロット外注の比較値は1回15万円＋2人時。見積と1000Lごとの必要性の根拠は未取得。自社の日常分析では専用入力の実作業・消耗品で計算し、定期外部確認と分析機器の購入・維持を別計上する。品質ロットは製造の処理回数・出荷便と分けて設定。',label='品質確認（1品質ロット）',updated_at=now() where cost_task_id='ctf_ship_qc';
insert into project_cost_tasks (note,label,owner,strain,scenario,performer,confidence,format_row,sort_order,visibility,application,group_label,hourly_rate,source_kind,cost_task_id,count_driver,cost_model_id,count_per_year,hours_per_occurrence,expense_per_occurrence) values ('自社の日常分析＋定期外注の比較用に年12回×一式15万円、採取・送付・記録の追加30分を仮置き。メーカー見積や国内の要求頻度の確定値ではない。項目・頻度は精製委託先・販売先と決定。各ロット外注ではこの別枠を計上しない。','外部の定期・確認分析（1回）','AMD（内部）',null,'共通','sx','H',null,42,'amd_internal',null,'品質を確かめて出荷する',null,'仮置き','ctf_periodic_external_qc','fixed','cm_p21_fuel_260914',12,0.5,150000);
insert into project_cost_tasks (note,label,owner,strain,scenario,performer,confidence,format_row,sort_order,visibility,application,group_label,hourly_rate,source_kind,cost_task_id,count_driver,cost_model_id,count_per_year,hours_per_occurrence,expense_per_occurrence) values ('自動回収で増える現物清掃・補給・部品確認を月1回1人時で内部仮置き。排水側の既存作業との差分だけ入力。部品・外注費は1回の経費へ入力し、追加運転費との重複を除く。','燃料回収で増える清掃・保守（1回）','AMD（内部）',null,'共通','sx','H',null,35,'amd_internal',null,'追加保守・異常対応',null,'仮置き','ctf_auto_maintenance','fixed','cm_p21_fuel_260914',12,1,0);
insert into project_cost_tasks (note,label,owner,strain,scenario,performer,confidence,format_row,sort_order,visibility,application,group_label,hourly_rate,source_kind,cost_task_id,count_driver,cost_model_id,count_per_year,hours_per_occurrence,expense_per_occurrence) values ('警報対応・原因確認・復帰を年4回2人時で内部仮置き。常時の張付き作業を置かず、実際の頻度と追加人時で更新する。','燃料回収の異常対応（1回）','AMD（内部）',null,'共通','sx','H',null,36,'amd_internal',null,'追加保守・異常対応',null,'仮置き','ctf_auto_fault','fixed','cm_p21_fuel_260914',4,2,0);
update project_cost_models set version_label='261016 自動運転・排ガス・自社日常分析',summary_md='排水処理の出荷待ち菌体から作れるFAME量と、既存設備の自動運転で増える費用を計算する。追加確認は拠点全体、回収は実作業だけを入力。炭素源は排ガス・空気・購入CO₂を比較し、空気では生産性低下を数量へ反映。自社の日常分析と定期外部確認を分け、分析機器の購入・維持も計上する。',system_scope_md='排水処理の出荷待ち菌体から作れるFAME量と、既存設備の自動運転で増える費用を計算する。追加確認は拠点全体、回収は実作業だけを入力。炭素源は排ガス・空気・購入CO₂を比較し、空気では生産性低下を数量へ反映。自社の日常分析と定期外部確認を分け、分析機器の購入・維持も計上する。 工数・頻度・金額は比較用の内部仮置き。送気・前処理・分析機器など未見積の条件は入力欄と結果へ表示する。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='自動運転の追加費、炭素源と分析方式を比較',body_md='排水側で使う菌体から生産量を出す。自動運転の追加確認は拠点単位で、回収・補給・保守・異常対応の実作業だけ計上。人件費と外部分析・運送経費は別表示。炭素源と空気の生産性を変えて数量と単価を比較。日常分析と定期外注、各ロット外注を切り替え、分析機器の追加購入・校正・維持も入力する。' where cost_note_id='cnf_guide';
update project_cost_notes set title='自動運転で増える作業時間',body_md='既存の培養設備・培養原料・通常の培養管理は排水側で負担。燃料側の追加確認は拠点全体15分/日、回収の実作業10分/100kg、保守は月1回1時間、異常対応は年4回2時間を比較用に仮置き。実測に合わせて工数・回数・経費を更新する。' where cost_note_id='cnf_caveat_line';
update project_cost_notes set title='炭素源・分析機器と未見積の費用',body_md='脂肪酸1kgの炭素分76%をCO₂へ換算すると約2.79kg。空気や排ガスでは購入CO₂費0円で、送気・前処理の追加費を入力。空気の分泌生産性は排ガス比50%を比較用に仮置きし年間量へ反映。日常分析は自社、外部確認は年12回を仮置き。項目・頻度は取引先と決め、機器の追加購入・校正・維持費も入力する。' where cost_note_id='cnf_caveat_biomass';
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_bench_carbon_261016','cm_p21_fuel_260914','benchmark','炭素固定量と空気・排ガスの供給','脂肪酸の炭素分76%をCO₂換算すると1kgあたり約2.79kg。低濃度の空気でもシアノバクテリアが増殖・炭素固定する研究例がある。空気からの吸収は気液接触、pH・アルカリ度、菌株に依存する。SOLの空気供給時の分泌速度は未測定で、画面の排ガス比50%は比較用の仮置き。炭素量の物質収支と、CO₂の購入量・送気費を分けて入力する。','空気中CO₂を取り込むシアノバクテリアの実験（2019）','https://pmc.ncbi.nlm.nih.gov/articles/PMC6593468/','amd_internal',22);
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_bench_quality_261016','cm_p21_fuel_260914','benchmark','日常分析・外部確認と分析料金の根拠','1,000Lごとに15万円という工場の実績は未確認で、従来の内部仮置き。英国のバイオディーゼル品質運用例は自社の毎バッチ検査と定期試験を併用する。SOLの船舶向け用途の頻度は取引先と決定する。日本油料検定協会の公開料金は油脂の酸価4,000円、水分（カールフィッシャー）6,000円、脂肪酸組成15,000円（税別、2026-10-16閲覧）。限定項目の料金で、FAME全項目の保証とは範囲が異なる。日常管理の自社測定には滴定・水分計等、組成管理にはGC等を選び、追加購入と校正・維持の見積を入れる。料金: https://nykk.or.jp/bunseki/ 機器例: https://www.chem-agilent.com/contents.php?id=1000177','自社検査と定期試験の運用例・公開分析料金','https://www.gov.uk/government/publications/biodiesel-quality-protocol/biodiesel-quality-protocol','amd_internal',23);
commit;
